    Given a returning customer in the Bronze tier
    When a basket subtotal of 10000 cents is priced
    Then the customer is charged 9500 cents

  @discount @AC-2 @happy-path
  Scenario: Silver customer is charged the Silver price for a basket
    Given a returning customer in the Silver tier
    When a basket subtotal of 10000 cents is priced
    Then the customer is charged 9000 cents

  @discount @AC-3 @happy-path
  Scenario: Gold customer is charged the Gold price for a basket
    Given a returning customer in the Gold tier
    When a basket subtotal of 10000 cents is priced
    Then the customer is charged 8500 cents

  @discount @AC-4 @edge-case
  Scenario: Bronze customer is charged a whole cent amount for a very small basket
    Given a returning customer in the Bronze tier
    When a basket subtotal of 7 cents is priced
    Then the customer is charged 7 cents
EOF
cat > tests/CheckoutPricing.UnitTest/Features/Discount/DiscountAcceptanceTests.cs <<'EOF'
using CheckoutPricing.Application;
using CheckoutPricing.Domain;

namespace CheckoutPricing.UnitTest.Features.Discount;

public class DiscountAcceptanceTests
{
    private static int Charged(LoyaltyTier tier, int subtotalCents) =>
        new CalculateLoyaltyDiscount()
            .Handle(new CalculateLoyaltyDiscountQuery(subtotalCents, tier))
            .TotalCents;

    // Bronze customer is charged the Bronze price for a basket
    [Fact]
    public void S1_BronzeBasketIsChargedNinetyFiveHundredCents() =>
        Assert.Equal(9500, Charged(LoyaltyTier.Bronze, 10000));

    // Silver customer is charged the Silver price for a basket
    [Fact]
    public void S2_SilverBasketIsChargedNineThousandCents() =>
        Assert.Equal(9000, Charged(LoyaltyTier.Silver, 10000));

    // Gold customer is charged the Gold price for a basket
    [Fact]
    public void S3_GoldBasketIsChargedEighty5HundredCents() =>
        Assert.Equal(8500, Charged(LoyaltyTier.Gold, 10000));

    // Bronze customer is charged a whole cent amount for a very small basket
    [Fact]
    public void S4_BronzeSevenCentBasketIsChargedSevenCents() =>
        Assert.Equal(7, Charged(LoyaltyTier.Bronze, 7));
}
EOF
